update public.fields set verification_status='needs_engineer_review', verification_quote='The initiatives were grouped into conceptual categories based on the narrative and terminology used by the investor or coalition. Thus, categorization provides a snapshot of the types of actions pursued by financial institutions and coalitions. Seven categories emerged from the 130 initiatives analyzed. | Multiple Assessment of alignment Climate lobbying Shareholder engagement Divestment/Exclusion Portfolio decarbonisation Climate-­‐related risks assessment Green Investment — §1.1 + Figure 1, p.5', verification_note='pdf-verified 2026-09-08 (§1.1 + Figure 1, p.5) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; the seven enum labels are the Figure 1 bar labels on p.5; the eighth bar "Multiple" is a residual bucket and is correctly not an enum value', verified_at=now() where id='22a23dee-26f2-404b-9345-68d8cd21f320' and verification_status not in ('verified_against_standard','corrected');

