-- ISO-14097-04 financial_function  (quote 396 chars)
update public.fields set verification_status='needs_engineer_review', verification_quote='Financial institutions develop various financial activities that can have an impact on climate (contribution) or contribute to mitigate climate-­‐related financial risks (risk management), they notably include: Origination of loans and deals, Services of underwriting of equity and debt, Securitization, Design of derivative contracts, Asset-­‐management, Investment product packaging and retail. — §3.2, p.40', verification_note='pdf-verified 2026-09-08 (§3.2, p.40) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; printed as an OPEN list ("they notably include"), and p.40 adds "hundreds of support services"; the enum closes it', verified_at=now() where id='fb7bba85-aa49-46b0-a0d9-67522c9da3be' and verification_status not in ('verified_against_standard','corrected');

