update public.fields set verification_status='needs_engineer_review', verification_quote='we suggest the ISO 14097 working group to focus on the functions of investment portfolio (see above) and loan book management, assuming that the standard created will be adapted to other services at a second stage. The scope of the standard will exclude all actions that are not specific to the finance sector, such as lobbying activities, and operational GHG emissions management — §3.2, p.40', verification_note='pdf-verified 2026-09-08 (§3.2, p.40) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; a suggestion to the working group about the scope of the future standard', verified_at=now() where id='dabaa993-1f4c-4ebb-a564-34816445b294' and verification_status not in ('verified_against_standard','corrected');

