-- ISO-14097-04 climate_action  (quote 616 chars)
update public.fields set verification_status='needs_engineer_review', verification_quote='In the context of investment portfolio and loan book management, financial institutions undertake a number of ‘actions’ that can contribute to climate-­‐related risk management and/or support the achievement of climate goals, as opposed to a ‘business as usual’ approach. The table below lists these core actions for illustrative purposes. The standardization work will involve further developing and documenting this list and turning it into a ‘library’ of climate-­‐related actions. | Blacklist/limit exposure to certain projects VC, PE, real assets Invest more in certain projects Set climate-­‐related conditions — §3.3 table, p.40', verification_note='pdf-verified 2026-09-08 (§3.3 table, p.40) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; illustrative list, explicitly not yet a library; 17 printed action rows were collapsed into 13 enum values, and the printed row "Change risk weights and related capital charges" carries NO asset label in the rendered table', verified_at=now() where id='bd9df002-04da-4fd9-907b-078a5e6fe82b' and verification_status not in ('verified_against_standard','corrected');

-- ISO-14097-05 risk_linkage_mechanism  (quote 591 chars)
update public.fields set verification_status='needs_engineer_review', verification_quote='These actions are linked to risk management in four ways: Limiting the exposure to assets perceived as ‘more risky’ (e.g. high cost oil extraction, coal power) than currently reflected in risk pricing | Similarly, increasing the exposure to other activities positively exposed to climate-­‐related opportunities (e.g. renewable power, electric vehicles) for which the market might undervalue the potential. | Influencing risk mitigation actions by the investee/issuer, by setting conditions. Hedging a risk by getting exposed to an instrument (security, derivative) with reverse correlation. — §3.4.1, p.41', verification_note='pdf-verified 2026-09-08 (§3.4.1, p.41) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; four printed ways, matching the four enum values one-for-one', verified_at=now() where id='50fdb459-2e08-4226-9c84-d88727aa65ac' and verification_status not in ('verified_against_standard','corrected');

