-- ISO-14097-06 contribution_linkage_mechanism  (quote 755 chars)
update public.fields set verification_status='needs_engineer_review', verification_quote='These actions can contribute to climate goals in three ways: Limiting the exposure to activities perceived as ‘misaligned with climate goals | Similarly, increasing the exposure to activities that need to further expand under a climate scenario (e.g. renewable power, electric vehicles) that can contribute to improve the availability and cost of capital for the related companies and thus support their expansion. | Finally shareholder engagement (e.g. use of voting rights to push climate-­‐related resolutions), climate-­‐related conditionality for lending or direct investments, and the signal sent by investment and divestment decisions can influence the investment plans and operational decisions of the investees, in a way that saves GHG emissions. — §3.4.2, p.41', verification_note='pdf-verified 2026-09-08 (§3.4.2, p.41) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; three printed ways, matching the three enum values one-for-one', verified_at=now() where id='0d31c182-4d6b-40ee-9012-3fe9ae90058f' and verification_status not in ('verified_against_standard','corrected');

