update public.fields set verification_status='needs_engineer_review', verification_quote='In this context, a key task of the ISO 14097 working group will involve defining the ‘pathways to impact’ on GHG emissions associated with different actions, and provide guidance on how to track the impact and influence on investees’ climate-­‐related decisions. This work will involve defining metrics to assess the ‘starting point’, set targets, and estimate the outcomes of actions. — §3.4.2, p.42', verification_note='pdf-verified 2026-09-08 (§3.4.2, p.42) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; named as a future task of the working group; the source defines no pathway and sets no acceptance criterion', verified_at=now() where id='e041b443-d10d-4194-a62a-eb07ceb57da0' and verification_status not in ('verified_against_standard','corrected');

