update public.fields set verification_status='needs_engineer_review', verification_quote='One of the main reason for that, illustrated in figure 1 below, is the confusion between: Changes due to the sale or acquisition of securities (see 1 in the figure 1) Changes due to an evolution of the scope of the issuer (see 2 in figure 1), and Changes due to actual evolution of assets and activities in the real economy (see 3 in figure 1) | Level 1 and 2 contribute to an evolution of the indicator but only due to ‘accounting effects | Another frequent bias relates to the use of volatile denominators in the calculation of ratios (e.g. CO2/$ of sales that can be exposed to fluctuations of prices) that ‘pollute’ the performance indicator. — §3.5.1, p.43', verification_note='pdf-verified 2026-09-08 (§3.5.1, p.43) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field', verified_at=now() where id='84f1d59f-48ac-4b3a-8ab5-ff3c54d78db9' and verification_status not in ('verified_against_standard','corrected');

