-- ISO-14097-09 standard_stage  (quote 543 chars)
update public.fields set verification_status='needs_engineer_review', verification_quote='At a first stage the standard will focus on developing a framework to assess the contribution of investments to the Paris Agreement, this will include the process to set targets, climate actions and the metrics to measure progress on targets and the impact of actions. Standardization avenues around scenarios will be as well be considered. At a second stage the group will focus on developing a framework for the management of climate-­‐related risks however the granularity of the standard on this topic will be discussed at a further stage. — §4, p.45', verification_note='pdf-verified 2026-09-08 (§4, p.45) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; describes the intended staging of a standard that did not yet exist in Nov 2017', verified_at=now() where id='a0780b07-1e62-4e70-92f6-ce57f6d9cb13' and verification_status not in ('verified_against_standard','corrected');

-- ISO-14097-09 priority_topic  (quote 374 chars)
update public.fields set verification_status='needs_engineer_review', verification_quote='Building on the landscape review and the recommendations provided the by ISO 14097 conveners, the ISO 14097 WG discussed the advantages and disadvantages of addressing a series of topics in the standard. The discussion led to the definition of the the priorities of the standard. | The main points to be addressed during the development of the standard are summarized below. — §4 tables, pp.45-47', verification_note='pdf-verified 2026-09-08 (§4 tables, pp.45-47) [VA] - SOURCE IS THE NOV-2017 WG SCOPING DOCUMENT, NOT THE PUBLISHED ISO 14097: descriptive/advisory text, no normative requirement behind this field; the nine enum values are the TOPIC / sub-topic cells of the pp.45-47 tables; those cells cannot be quoted contiguously because the text layer interleaves all four table columns', verified_at=now() where id='7f80574a-9252-4859-aca1-c3349428c395' and verification_status not in ('verified_against_standard','corrected');

